WITH "r0" AS ( SELECT "s".* FROM "public"."author" AS "s" WHERE true AND ( ( true AND ( ( true ) ) AND ( ( true ) ) ) ) ORDER BY "s"."id" DESC NULLS FIRST ) SELECT row_to_json((SELECT "%" FROM (SELECT coalesce(array_to_json((array_agg( "c0"."j" ORDER BY "t0"."id" DESC NULLS FIRST ))[1: 2 ]), '[]') AS "nodes" ) AS "%")) FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."name" AS "name" ) AS "%")) AS "j" FROM (SELECT true) AS "_" ) AS "c0" ON true
